function WorkspaceSetup({ userName }: { userName?: string | null }) {
  const utils = trpc.useUtils();
  const create = trpc.workspace.create.useMutation({ onSuccess: async () => { await utils.workspace.bootstrap.invalidate(); toast.success("Your VisionRoute workspace is ready."); } });
  const [category, setCategory] = useState("business");
  const [includeDemo, setIncludeDemo] = useState(true);
  const terms = terminologyForCategory(category);
  const submit = async (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    const form = new FormData(event.currentTarget);
    await create.mutateAsync({ organizationName: String(form.get("organizationName")), portalName: String(form.get("portalName") || form.get("organizationName")), coachingCategory: category as "business", website: String(form.get("website") || ""), brandColor: String(form.get("brandColor") || "#0F766E"), welcomeMessage: String(form.get("welcomeMessage") || ""), terminology: terms, includeDemo });
  };
  return <main className="min-h-screen bg-[#f6f4ee] px-5 py-10"><div className="mx-auto max-w-5xl"><div className="mb-10 flex items-center justify-between"><Logo /><span className="text-sm font-semibold text-[#567077]">Welcome, {userName || "Coach"}</span></div><div className="grid overflow-hidden rounded-[2rem] border border-[#d7e2dc] bg-white shadow-[0_22px_65px_rgba(18,42,49,.08)] lg:grid-cols-[.9fr_1.1fr]"><aside className="bg-[#102a31] p-8 text-white sm:p-11"><p className="text-xs font-extrabold tracking-[.15em] text-[#8bd0bf]">SET UP YOUR PORTAL</p><h1 className="mt-4 text-4xl font-semibold tracking-[-.06em]">Start with the coaching method you already trust.</h1><p className="mt-5 leading-7 text-[#b9cdcc]">VisionRoute creates one secure coaching workspace. Your terminology and branding are configuration — not a separate product.</p><div className="mt-10 space-y-5">{[["01", "Create your account", "Business, category and brand"],["02", "Explore the demo", "A labelled client route to learn from"],["03", "Invite a real client", "Securely join the right workspace"]].map(([n, title, text]) => <div key={n} className="flex gap-4"><span className="font-black text-[#77c5b2]">{n}</span><div><p className="font-bold">{title}</p><p className="mt-1 text-sm text-[#9db8b8]">{text}</p></div></div>)}</div></aside><form onSubmit={submit} className="p-8 sm:p-11"><p className="eyebrow">Your coaching account</p><h2 className="mt-2 text-3xl font-semibold tracking-[-.05em]">Name the workspace clients will enter.</h2><div className="mt-8 grid gap-5 sm:grid-cols-2"><label className="sm:col-span-2"><span className="field-label">Business name</span><input className="field" name="organizationName" required placeholder="Northstar Coaching" /></label><label><span className="field-label">Portal name</span><input className="field" name="portalName" placeholder="Northstar Route" /></label><label><span className="field-label">Coaching category</span><select className="field" value={category} onChange={event => setCategory(event.target.value)}><option value="business">Business coaching</option><option value="entrepreneur">Entrepreneur coaching</option><option value="sports">Sports coaching</option><option value="athletic_performance">Athletic performance</option><option value="personal_training">Personal training</option></select></label><label><span className="field-label">Website (optional)</span><input className="field" name="website" type="url" placeholder="https://" /></label><label><span className="field-label">Brand color</span><div className="flex gap-2"><input className="h-11 w-12 rounded-lg border border-[#d6e0da] p-1" name="brandColor" type="color" defaultValue="#0F766E" /><input className="field" defaultValue="#0F766E" aria-label="Brand color hex value" /></div></label><label className="sm:col-span-2"><span className="field-label">Welcome message</span><textarea className="field min-h-22" name="welcomeMessage" placeholder="A calm, focused place to keep your route moving between our sessions." /></label></div><label className="mt-6 flex items-start gap-3 rounded-xl bg-[#eff7f2] p-4"><input className="mt-1 h-4 w-4 accent-[#0f766e]" type="checkbox" checked={includeDemo} onChange={event => setIncludeDemo(event.target.checked)} /><span><span className="block text-sm font-bold">Add a labelled demo workspace</span><span className="mt-1 block text-xs leading-5 text-[#5d777b]">See a sample client, route, completed and missed action, check-in, reroute and coach brief before inviting a client.</span></span></label>{create.error && <p className="mt-4 text-sm text-[#a04438]">{create.error.message}</p>}<button disabled={create.isPending} className="vr-button mt-7 w-full">{create.isPending ? "Creating workspace…" : "Create VisionRoute workspace"} <ArrowRight size={17} /></button></form></div></div></main>;
}

function CapacityControl({ tenantId, clientId, capacity, terminology, onUpdated }: { tenantId: string; clientId: string; capacity: "low" | "normal" | "high"; terminology: Terminology; onUpdated: () => void }) {
  const mutation = trpc.clients.setCapacity.useMutation({ onSuccess: onUpdated });
  return <div><p className="field-label">{terminology.capacity}</p><div className="grid grid-cols-3 gap-2">{(["low", "normal", "high"] as const).map(level => <button key={level} onClick={() => mutation.mutate({ tenantId, clientId, capacity: level })} className={`rounded-xl border px-3 py-2 text-xs font-extrabold capitalize transition ${capacity === level ? "border-[#0f766e] bg-[#e2f4ec] text-[#0b635a]" : "border-[#d9e3dd] bg-white text-[#5b7478] hover:border-[#92bdb2]"}`}>{level}</button>)}</div>{capacity === "low" && <p className="mt-2 text-xs leading-5 text-[#a66112]">Low capacity protects the most important action and reduces the workload.</p>}</div>;
}

function InviteClient({ tenantId, onCreated }: { tenantId: string; onCreated: () => void }) {
  const [open, setOpen] = useState(false);
  const [result, setResult] = useState<{ invitationToken: string; delivery: string } | null>(null);
  const invite = trpc.clients.createInvitation.useMutation({ onSuccess: () => onCreated() });
  const submit = async (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); const data = new FormData(event.currentTarget); const value = await invite.mutateAsync({ tenantId, name: String(data.get("name")), email: String(data.get("email")) }); setResult(value); };
  return <><button className="vr-button" onClick={() => { setOpen(true); setResult(null); }}><Plus size={16} /> Invite client</button>{open && <div className="fixed inset-0 z-50 grid place-items-center bg-[#102a31]/40 p-4"><div className="w-full max-w-md rounded-3xl bg-white p-7 shadow-2xl"><div className="flex items-start justify-between"><div><p className="eyebrow">Client invitation</p><h3 className="mt-1 text-2xl font-bold tracking-tight">Invite a client securely.</h3></div><button onClick={() => setOpen(false)} className="rounded-lg p-2"><X size={20} /></button></div>{result ? <div className="mt-6 space-y-4"><div className="rounded-xl bg-[#eff7f2] p-4"><p className="text-sm font-bold">Invitation created</p><p className="mt-1 text-xs leading-5 text-[#587078]">{result.delivery === "queued" ? "Email delivery is queued." : "Email provider is not configured. Copy this secure, single-use development link to test acceptance."}</p></div><div className="rounded-xl border border-[#d6e0da] bg-[#f8fbf9] p-3 text-xs break-all">{`${window.location.origin}/invite/${result.invitationToken}`}</div><button className="vr-button secondary w-full" onClick={async () => { await navigator.clipboard.writeText(`${window.location.origin}/invite/${result.invitationToken}`); toast.success("Invitation link copied."); }}>Copy invitation link</button></div> : <form onSubmit={submit} className="mt-6 space-y-4"><label><span className="field-label">Client name</span><input className="field" name="name" required placeholder="Jane Smith" /></label><label><span className="field-label">Client email</span><input className="field" name="email" required type="email" placeholder="jane@example.com" /></label>{invite.error && <p className="text-sm text-[#a04438]">{invite.error.message}</p>}<button disabled={invite.isPending} className="vr-button w-full">{invite.isPending ? "Creating invitation…" : "Create invitation"} <Send size={16} /></button></form>}</div></div>}</>;
}

function CoachBrief({ tenantId, clientId }: { tenantId: string; clientId: string }) {
  const [visible, setVisible] = useState(false);
  const brief = trpc.briefs.get.useQuery({ tenantId, clientId }, { enabled: visible });
  if (!visible) return <section className="vr-card p-7"><p className="eyebrow">AI pre-session brief</p><h3 className="mt-2 text-2xl font-semibold tracking-tight">Arrive at the next coaching conversation oriented.</h3><p className="mt-3 max-w-xl leading-7 text-[#5e787c]">The brief keeps source data, client-reported information, private coach notes and AI interpretation visibly separate.</p><button onClick={() => setVisible(true)} className="vr-button mt-6"><Sparkles size={16} /> Generate current brief</button></section>;
  if (brief.isLoading) return <section className="vr-card p-8"><Loader2 className="animate-spin text-[#0f766e]" /> <p className="mt-3 font-semibold">Preparing a structured brief…</p></section>;
  if (!brief.data) return <section className="vr-card p-7 text-[#a04438]">{brief.error?.message || "Brief unavailable."}</section>;
  const groups: Array<[string, string[], string]> = [["System data", brief.data.systemData, "#eaf1ef"], ["Client-reported information", brief.data.clientReported, "#e8f5f0"], ["Coach notes", brief.data.coachNotes, "#f7f0e8"], ["AI interpretation — not fact", brief.data.aiInterpretation, "#f5eee9"]];
  return <section className="vr-card p-6 sm:p-8"><div className="flex flex-wrap items-start justify-between gap-4"><div><p className="eyebrow">AI pre-session brief</p><h3 className="mt-2 text-2xl font-semibold tracking-tight">What to bring into the next session.</h3></div><StatusPill tone="amber"><Sparkles size={12} /> Interpretation labelled</StatusPill></div><div className="mt-7 grid gap-3 md:grid-cols-2">{groups.map(([title, items, color]) => <div key={title} className="rounded-2xl p-5" style={{ background: color }}><p className="text-[10px] font-black tracking-[.13em] text-[#5d777b]">{title}</p><ul className="mt-3 space-y-2 text-sm leading-6 text-[#2d4a50]">{items.map(item => <li key={item}>• {item}</li>)}</ul></div>)}</div><div className="mt-4 rounded-2xl border border-[#cfe5dc] bg-[#f7fffb] p-5"><p className="text-[10px] font-black tracking-[.13em] text-[#0f766e]">Suggested coaching discussion</p><p className="mt-2 font-semibold leading-7">{brief.data.suggestedDiscussion}</p></div></section>;
}

function CheckoutButton({ tenantId, planKey, label }: { tenantId: string; planKey: "visionroute_coach" | "founding_white_label"; label: string }) {
  const checkout = trpc.billing.createCheckout.useMutation({ onSuccess: result => window.open(result.url, "_blank", "noopener,noreferrer") });
  return <button disabled={checkout.isPending} onClick={() => checkout.mutate({ tenantId, planKey, origin: window.location.origin })} className="vr-button mt-5 w-full">{checkout.isPending ? "Opening secure checkout…" : label} <ArrowRight size={16} /></button>;
}

function ClientWorkspace({ tenantId, clientId, role, terminology, panel, setPanel, onBack }: { tenantId: string; clientId: string; role: string; terminology: Terminology; panel: Panel; setPanel: (panel: Panel) => void; onBack: () => void }) {
  const detail = trpc.clients.detail.useQuery({ tenantId, clientId });
  const utils = trpc.useUtils();
  const complete = trpc.planning.completeAction.useMutation({ onSuccess: async () => { await detail.refetch(); await utils.workspace.bootstrap.invalidate(); toast.success("Action completed. Your route has updated."); } });
  const decide = trpc.planning.decideRoute.useMutation({ onSuccess: async () => { await detail.refetch(); toast.success("Route decision saved."); } });
  const generate = trpc.planning.generateRoute.useMutation({ onSuccess: async result => { await detail.refetch(); toast.success(result.realityCheck.message); } });
  const checkin = trpc.checkins.submit.useMutation({ onSuccess: async () => { await detail.refetch(); toast.success("Check-in submitted for coach review."); } });
  const reroute = trpc.reroutes.create.useMutation({ onSuccess: async () => { await detail.refetch(); toast.success("Choose one recovery path for coach review."); } });
  const selectReroute = trpc.reroutes.select.useMutation({ onSuccess: async () => { await detail.refetch(); toast.success("Recovery path sent to your coach for approval."); } });
  const resolve = trpc.reroutes.resolve.useMutation({ onSuccess: async () => { await detail.refetch(); toast.success("Reroute decision recorded."); } });
  const note = trpc.clients.addCoachNote.useMutation({ onSuccess: async () => { await detail.refetch(); toast.success("Private coach note added."); } });
  const [rerouteId, setRerouteId] = useState<string | null>(null);
  const rerouteOptions = trpc.reroutes.options.useQuery({ tenantId, rerouteId: rerouteId || "00000000-0000-0000-0000-000000000000" }, { enabled: Boolean(rerouteId) });

  if (detail.isLoading) return <div className="grid min-h-[50vh] place-items-center"><div className="text-center"><Loader2 className="mx-auto animate-spin text-[#0f766e]" size={30} /><p className="mt-3 text-sm font-semibold text-[#60797d]">Loading the route…</p></div></div>;
  if (!detail.data) return <div className="vr-card p-8 text-[#a04438]">{detail.error?.message || "This client workspace is unavailable."}</div>;
  const { client, goal, route, milestones, actions, progress, nextAction, checkIns, reroutes, notes } = detail.data;
  const isCoach = role !== "client";
  const activeReroute = reroutes.find((item: any) => item.status === "proposed");
  const selectedReroute = reroutes.find((item: any) => item.id === rerouteId);

  return <div className="space-y-6"><button onClick={onBack} className="vr-button ghost -ml-1"><ChevronRight size={16} className="rotate-180" /> All clients</button><section className="rounded-[1.6rem] border border-[#d9e4de] bg-white p-6 shadow-[0_10px_28px_rgba(17,38,43,.04)] sm:p-8"><div className="flex flex-col justify-between gap-6 lg:flex-row lg:items-start"><div className="flex gap-4"><div className="flex h-13 w-13 shrink-0 items-center justify-center rounded-2xl bg-[#e2f1ec] text-lg font-black text-[#0f766e]">{client.name.split(" ").map((word: string) => word[0]).join("").slice(0, 2)}</div><div><div className="flex flex-wrap items-center gap-2"><p className="text-2xl font-semibold tracking-[-.045em]">{client.name}</p>{client.isDemo && <StatusPill tone="slate">Sample data</StatusPill>}</div><p className="mt-1 text-sm text-[#617a7f]">{goal?.title || "Intake not complete"}</p><div className="mt-3 flex flex-wrap gap-2"><StatusPill tone={route?.status === "approved" ? "teal" : route ? "amber" : "slate"}>{route?.status === "approved" ? "Approved route" : route?.status === "proposed" ? "Awaiting approval" : "No route yet"}</StatusPill>{client.capacity === "low" && <StatusPill tone="amber">Low {terminology.capacity.toLowerCase()}</StatusPill>}{actions.filter((action: any) => action.status === "missed").length > 0 && <StatusPill tone="rose">{actions.filter((action: any) => action.status === "missed").length} missed action</StatusPill>}</div></div></div><div className="grid min-w-[185px] grid-cols-2 gap-3"><div className="rounded-xl bg-[#eff7f2] p-3"><p className="text-[10px] font-black tracking-[.12em] text-[#51736e]">PROGRESS</p><p className="mt-1 text-2xl font-bold text-[#0f766e]">{progress}%</p></div><div className="rounded-xl bg-[#f5f3ec] p-3"><p className="text-[10px] font-black tracking-[.12em] text-[#667c7d]">CAPACITY</p><p className="mt-1 text-lg font-bold capitalize">{client.capacity}</p></div></div></div></section>

    {panel === "overview" && <div className="grid gap-6 xl:grid-cols-[1.08fr_.92fr]"><section className="vr-card p-6 sm:p-8"><div className="flex items-center justify-between"><div><p className="eyebrow">Current focus</p><h2 className="mt-1 text-2xl font-semibold tracking-[-.045em]">The route at a glance.</h2></div><button onClick={() => setPanel("route")} className="vr-button ghost">Open route <ArrowRight size={15} /></button></div><div className="mt-8 route-line space-y-7">{milestones.slice(0, 4).map((milestone: any) => <div className={`route-stop ${milestone.status === "upcoming" ? "upcoming" : milestone.status === "complete" ? "complete" : ""}`} key={milestone.id}><i>{milestone.status === "complete" && <Check size={11} className="text-white" />}</i><div className="pb-1"><p className="text-[10px] font-black tracking-[.13em] text-[#638087]">{milestone.status === "active" ? "YOU ARE HERE" : `MILESTONE ${milestone.sequence}`}</p><p className="mt-1 font-bold">{milestone.title}</p><p className="mt-1 text-sm leading-6 text-[#658086]">{milestone.description}</p></div></div>)}{route && <div className="route-stop upcoming"><i><Flag size={10} /></i><div><p className="text-[10px] font-black tracking-[.13em] text-[#638087]">DESTINATION</p><p className="mt-1 font-bold">{route.destination}</p></div></div>}</div></section><section className="space-y-5"><div className="vr-card p-6"><div className="flex items-center gap-2"><Bolt size={18} className="text-[#0f766e]" /><p className="font-bold">Coach attention</p></div>{activeReroute ? <div className="mt-4 rounded-xl bg-[#fff3dd] p-4"><p className="font-bold text-[#935a16]">A reroute is ready to review.</p><p className="mt-1 text-sm text-[#765e42]">The client reported a change. Review recovery options before the plan changes.</p><button onClick={() => { setRerouteId(activeReroute.id); setPanel("reroute"); }} className="vr-button secondary mt-3">Review reroute</button></div> : <p className="mt-4 text-sm leading-6 text-[#607a7f]">No major route change is waiting for approval.</p>}</div><div className="vr-card p-6"><p className="font-bold">Private coach note</p><form className="mt-4" onSubmit={async event => { event.preventDefault(); const form = new FormData(event.currentTarget); await note.mutateAsync({ tenantId, clientId, body: String(form.get("body")) }); (event.target as HTMLFormElement).reset(); }}><textarea className="field min-h-24" name="body" required placeholder="Capture a private observation for the next session…" /><button disabled={note.isPending} className="vr-button secondary mt-3 w-full">Add private note</button></form></div></section></div>}

    {panel === "today" && <section className="mx-auto max-w-3xl"><div className="vr-card overflow-hidden"><div className="bg-[#102a31] p-7 text-white sm:p-9"><div className="flex flex-wrap items-start justify-between gap-5"><div><p className="text-xs font-black tracking-[.14em] text-[#8ed4c4]">TODAY</p><h2 className="mt-2 text-3xl font-semibold tracking-[-.05em]">One clear next step.</h2><p className="mt-3 max-w-lg leading-7 text-[#b7cccc]">{client.capacity === "low" ? "Low capacity is selected. Protect the most important action, then stop." : "Work the route, not the entire list. Complete this, then ask for the next action."}</p></div><StatusPill tone={client.capacity === "low" ? "amber" : "teal"}>{client.capacity} {terminology.capacity.toLowerCase()}</StatusPill></div></div><div className="p-7 sm:p-9"><CapacityControl tenantId={tenantId} clientId={clientId} capacity={client.capacity} terminology={terminology} onUpdated={() => detail.refetch()} />{nextAction ? <div className="mt-8 rounded-2xl border border-[#cfe6dc] bg-[#f2faf6] p-6"><div className="flex items-start justify-between gap-4"><div><p className="eyebrow">{terminology.nextAction}</p><h3 className="mt-2 text-xl font-semibold tracking-tight">{nextAction.title}</h3><p className="mt-2 text-sm leading-6 text-[#557177]">{nextAction.description}</p></div><span className="flex shrink-0 items-center gap-1 rounded-lg bg-white px-2.5 py-1.5 text-xs font-bold text-[#0f766e]"><Timer size={13} /> {nextAction.adjustedMinutes}m</span></div><p className="mt-5 text-sm font-semibold text-[#537176]">{nextAction.guidance}</p><button disabled={complete.isPending} onClick={() => complete.mutate({ tenantId, actionId: nextAction.id })} className="vr-button mt-6">{complete.isPending ? "Saving…" : "Done — give me the next action"} <ArrowRight size={16} /></button></div> : <div className="mt-8 rounded-2xl bg-[#eef4f1] p-6"><CheckCircle2 className="text-[#0f766e]" /><h3 className="mt-3 text-xl font-bold">Today’s route is clear.</h3><p className="mt-2 text-sm text-[#5b767b]">There are no pending actions in the current route.</p></div>}</div></div></section>}

    {panel === "route" && <section className="grid gap-6 xl:grid-cols-[1.1fr_.9fr]"><div className="vr-card p-6 sm:p-8"><div className="flex flex-wrap justify-between gap-5"><div><p className="eyebrow">Route</p><h2 className="mt-2 text-3xl font-semibold tracking-[-.055em]">{route?.destination || "A route is waiting to be generated."}</h2>{route?.targetDate && <p className="mt-2 text-sm text-[#637d81]">Destination date: {new Date(route.targetDate).toLocaleDateString(undefined, { month: "long", day: "numeric", year: "numeric" })}</p>}</div>{Boolean(route?.realityCheck) && <StatusPill tone={(route?.realityCheck as any).isRealistic ? "teal" : "amber"}>{(route?.realityCheck as any).isRealistic ? "Capacity aligned" : "Reality check"}</StatusPill>}</div>{Boolean(route?.realityCheck) && <p className="mt-6 rounded-xl bg-[#f2f6f4] p-4 text-sm leading-6 text-[#49676c]">{(route?.realityCheck as any).message}</p>}<div className="mt-8 route-line space-y-8">{milestones.map((milestone: any) => <div className={`route-stop ${milestone.status === "upcoming" ? "upcoming" : milestone.status === "complete" ? "complete" : ""}`} key={milestone.id}><i>{milestone.status === "complete" ? <Check size={11} className="text-white" /> : milestone.status === "active" ? <CircleDot size={10} className="text-white" /> : null}</i><div className="w-full pb-1"><div className="flex flex-wrap justify-between gap-2"><p className="font-bold">{milestone.title}</p><span className="text-xs font-semibold capitalize text-[#698287]">{milestone.status}</span></div><p className="mt-1 text-sm leading-6 text-[#628086]">{milestone.description}</p></div></div>)}</div>{!route && goal && <button disabled={generate.isPending} onClick={() => generate.mutate({ tenantId, clientId })} className="vr-button mt-8">{generate.isPending ? "Generating route…" : "Generate proposed route"} <Sparkles size={16} /></button>}{route?.status === "proposed" && isCoach && <div className="mt-8 flex flex-wrap gap-3 rounded-2xl border border-[#efd9ad] bg-[#fff9ed] p-5"><div className="mr-auto"><p className="font-bold text-[#80551f]">Coach approval required</p><p className="mt-1 text-sm text-[#7a6544]">AI has suggested this route. Review before it becomes visible to the client.</p></div><button disabled={decide.isPending} onClick={() => decide.mutate({ tenantId, routeId: route.id, decision: "approve" })} className="vr-button">Approve route</button><button disabled={decide.isPending} onClick={() => decide.mutate({ tenantId, routeId: route.id, decision: "reject" })} className="vr-button secondary">Reject</button></div>}</div><div className="vr-card p-6"><div className="flex items-center justify-between"><div><p className="eyebrow">Execution categories</p><h3 className="mt-2 text-xl font-semibold tracking-tight">Keep attention intentional.</h3></div><Network size={22} className="text-[#0f766e]" /></div><div className="mt-6 space-y-5">{(["active", "maintain", "next", "park"] as const).map(category => { const categoryActions = actions.filter((action: any) => action.category === category); return <div key={category}><div className="flex items-center justify-between"><p className="text-[10px] font-black tracking-[.14em] uppercase text-[#5d777a]">{category}</p><span className="text-xs font-bold text-[#82979a]">{categoryActions.length}</span></div><div className="mt-2 space-y-2">{categoryActions.length ? categoryActions.map((action: any) => <div key={action.id} className="rounded-xl bg-[#f5f7f5] px-3 py-2.5"><p className={`text-sm font-semibold ${action.status === "completed" ? "line-through text-[#84979a]" : ""}`}>{action.title}</p><p className="mt-1 text-xs text-[#789094]">{action.estimatedMinutes} min · {action.status}</p></div>) : <p className="text-xs text-[#8a9b9b]">No actions in this category.</p>}</div></div>; })}</div></div></section>}

    {panel === "checkin" && <section className="grid gap-6 xl:grid-cols-[.85fr_1.15fr]"><div className="vr-card p-7"><p className="eyebrow">Weekly check-in</p><h2 className="mt-2 text-2xl font-semibold tracking-tight">Report what really happened.</h2><p className="mt-3 leading-7 text-[#5c777c]">Your coach sees your original words. VisionRoute may add a labelled summary, never replace your report.</p><div className="mt-7 space-y-4">{checkIns.length ? checkIns.map((item: any) => <div key={item.id} className="rounded-xl bg-[#f2f6f4] p-4"><div className="flex justify-between gap-3"><p className="text-sm font-bold">{new Date(item.submittedAt).toLocaleDateString()}</p><StatusPill tone={item.needsReroute ? "amber" : "teal"}>{item.needsReroute ? "Reroute requested" : "Submitted"}</StatusPill></div><p className="mt-2 text-sm leading-6 text-[#5a757a]">{item.completedText}</p></div>) : <p className="rounded-xl bg-[#f2f6f4] p-4 text-sm text-[#607b80]">No check-ins submitted yet.</p>}</div></div><form className="vr-card p-7" onSubmit={async event => { event.preventDefault(); const form = new FormData(event.currentTarget); await checkin.mutateAsync({ tenantId, clientId, completedText: String(form.get("completedText")), obstacleText: String(form.get("obstacleText")), changedText: String(form.get("changedText")), prioritiesCorrect: form.get("prioritiesCorrect") === "on", needsReroute: form.get("needsReroute") === "on", capacity: client.capacity }); (event.target as HTMLFormElement).reset(); }}><p className="eyebrow">New check-in</p><h3 className="mt-2 text-2xl font-semibold tracking-tight">Close the loop.</h3><div className="mt-6 space-y-4"><label><span className="field-label">What did you complete?</span><textarea required name="completedText" className="field min-h-24" placeholder="What moved forward this week?" /></label><label><span className="field-label">What got in the way?</span><textarea name="obstacleText" className="field min-h-20" placeholder="An obstacle, concern or point of friction…" /></label><label><span className="field-label">What changed?</span><textarea name="changedText" className="field min-h-20" placeholder="Any changes in availability, priority or constraints…" /></label><div className="grid gap-3 sm:grid-cols-2"><label className="flex items-center gap-3 rounded-xl border border-[#dbe4de] p-3 text-sm font-semibold"><input name="prioritiesCorrect" type="checkbox" defaultChecked className="accent-[#0f766e]" /> Priorities still fit</label><label className="flex items-center gap-3 rounded-xl border border-[#ecd8b1] bg-[#fffaf1] p-3 text-sm font-semibold text-[#80561e]"><input name="needsReroute" type="checkbox" className="accent-[#a56615]" /> I need a reroute</label></div></div><button disabled={checkin.isPending} className="vr-button mt-6 w-full">{checkin.isPending ? "Submitting…" : "Submit weekly check-in"} <Send size={16} /></button></form></section>}

    {panel === "reroute" && <section className="grid gap-6 xl:grid-cols-[.82fr_1.18fr]"><div className="vr-card p-7"><p className="eyebrow">Reroute</p><h2 className="mt-2 text-2xl font-semibold tracking-tight">When the plan no longer fits reality.</h2><p className="mt-3 leading-7 text-[#5b777b]">VisionRoute does not simply push every late task forward. Start with what happened, then review recovery paths.</p><form className="mt-7 space-y-4" onSubmit={async event => { event.preventDefault(); const form = new FormData(event.currentTarget); const outcome = await reroute.mutateAsync({ tenantId, clientId, whatHappened: String(form.get("whatHappened")), triggerType: "client_request" }); setRerouteId(outcome.rerouteId); }}><label><span className="field-label">What happened?</span><select className="field" name="whatHappened"><option>I underestimated the work.</option><option>Something unexpected happened.</option><option>I procrastinated.</option><option>I had low energy.</option><option>Another priority became more important.</option><option>My schedule changed.</option><option>I was traveling.</option><option>I lacked equipment or resources.</option><option>I changed my mind.</option><option>I don&apos;t know.</option></select></label><button disabled={reroute.isPending} className="vr-button w-full">{reroute.isPending ? "Building recovery paths…" : "Generate recovery paths"} <Compass size={16} /></button></form></div><div className="vr-card p-7"><p className="eyebrow">Recovery paths</p><h3 className="mt-2 text-2xl font-semibold tracking-tight">{rerouteOptions.data ? "Choose how to recover." : "A reroute is a decision, not a delay."}</h3>{rerouteOptions.data ? <div className="mt-6 grid gap-3">{rerouteOptions.data.map((option: any) => <div key={option.id} className="rounded-2xl border border-[#dce6df] p-5"><div className="flex flex-wrap justify-between gap-3"><div><div className="flex items-center gap-2"><p className="font-bold">{option.title}</p>{option.recommended && <StatusPill>Recommended</StatusPill>}</div><p className="mt-2 text-sm leading-6 text-[#5f797d]">{option.summary}</p></div>{isCoach ? <div className="flex gap-2"><button disabled={resolve.isPending} onClick={() => resolve.mutate({ tenantId, rerouteId: rerouteId!, optionId: option.id, decision: "approve" })} className="vr-button">Approve</button><button disabled={resolve.isPending} onClick={() => resolve.mutate({ tenantId, rerouteId: rerouteId!, optionId: option.id, decision: "reject" })} className="vr-button secondary">Reject</button></div> : selectedReroute?.status === "awaiting_approval" ? <StatusPill tone="amber">Coach review required</StatusPill> : <button disabled={selectReroute.isPending} onClick={() => selectReroute.mutate({ tenantId, rerouteId: rerouteId!, optionId: option.id })} className="vr-button secondary">{selectReroute.isPending ? "Sending…" : "Select for coach review"}</button>}</div></div>)}</div> : <div className="mt-7 rounded-2xl bg-[#f2f6f4] p-6"><Compass className="text-[#0f766e]" /><p className="mt-3 font-bold">Keep the destination, move it, reduce scope, or change the sequence.</p><p className="mt-2 text-sm leading-6 text-[#678086]">Major goal, date, milestone, workload and locked-action changes never apply silently.</p></div>}</div></section>}

    {panel === "brief" && isCoach && <CoachBrief tenantId={tenantId} clientId={clientId} />}

    {panel === "settings" && isCoach && <section className="vr-card p-7"><p className="eyebrow">Portal configuration</p><h2 className="mt-2 text-2xl font-semibold tracking-tight">Configuration over customization.</h2><p className="mt-3 max-w-2xl leading-7 text-[#5a767b]">Your portal already uses tenant-scoped brand color, name, welcome message and terminology. Phase 1 exposes the core configuration at workspace setup and keeps it separate from client data.</p><div className="mt-7 grid gap-3 sm:grid-cols-3">{[[terminology.goal, "Primary destination"],[terminology.action, "Client commitment"],[terminology.milestone, "Route marker"]].map(([term, description]) => <div key={term} className="rounded-xl bg-[#eff7f2] p-4"><p className="text-lg font-bold">{term}</p><p className="mt-1 text-sm text-[#5d777a]">{description}</p></div>)}</div></section>}

    {panel === "billing" && isCoach && <section className="vr-card p-7"><div className="flex flex-wrap justify-between gap-5"><div><p className="eyebrow">Billing</p><h2 className="mt-2 text-2xl font-semibold tracking-tight">Stripe test mode is connected.</h2><p className="mt-3 leading-7 text-[#5a767b]">The app securely creates a Stripe test checkout, persists the subscription against this tenant, and verifies idempotent webhooks before changing entitlement state.</p></div><StatusPill tone="amber">Test mode</StatusPill></div><div className="mt-7 grid gap-4 sm:grid-cols-2"><div className="rounded-2xl border border-[#dce5df] p-5"><p className="font-bold">VisionRoute Coach</p><p className="mt-2 text-3xl font-semibold">$97<span className="text-sm font-medium text-[#6b8286]">/month</span></p><CheckoutButton tenantId={tenantId} planKey="visionroute_coach" label="Test coach checkout" /></div><div className="rounded-2xl border border-[#dce5df] p-5"><p className="font-bold">Founding Coach White-Label</p><p className="mt-2 text-3xl font-semibold">$499<span className="text-sm font-medium text-[#6b8286]"> setup</span></p><p className="mt-1 text-sm text-[#6b8286]">+ $97/month</p><CheckoutButton tenantId={tenantId} planKey="founding_white_label" label="Test founding checkout" /></div></div><p className="mt-5 text-sm leading-6 text-[#a66112]">Live charges are deliberately not enabled. In Stripe test mode, use test card <strong>4242 4242 4242 4242</strong>.</p></section>}
  </div>;
}

function WorkspaceShell({ boot }: { boot: any }) {
  const [panel, setPanel] = useState<Panel>("overview");
  const [selectedClientId, setSelectedClientId] = useState<string | null>(null);
  const [mobileOpen, setMobileOpen] = useState(false);
  const utils = trpc.useUtils();
  const { workspace, dashboard } = boot;
  const terminology = workspace.terminology as Terminology;
  const isCoach = workspace.membership.role !== "client";
  const cards = dashboard?.cards ?? [];
  const activeClientId = selectedClientId ?? cards[0]?.id ?? null;
  const exportCsv = trpc.workspace.exportCsv.useQuery({ tenantId: workspace.tenant.id }, { enabled: false });
  const downloadExport = async () => { const result = await exportCsv.refetch(); if (!result.data) return; const blob = new Blob([result.data.csv], { type: "text/csv" }); const link = document.createElement("a"); link.href = URL.createObjectURL(blob); link.download = result.data.filename; link.click(); URL.revokeObjectURL(link.href); };
  const selectedCard = cards.find((card: any) => card.id === activeClientId);

  if (selectedClientId && activeClientId && panel !== "settings") return <div className="min-h-screen bg-[#f6f4ee]"><main className="mx-auto max-w-7xl px-5 py-8 lg:px-8"><ClientWorkspace tenantId={workspace.tenant.id} clientId={activeClientId} role={workspace.membership.role} terminology={terminology} panel={panel} setPanel={setPanel} onBack={() => { setSelectedClientId(null); setPanel("overview"); }} /></main></div>;
  return <div className="min-h-screen bg-[#f6f4ee]" style={{ "--teal": workspace.tenant.brandColor } as React.CSSProperties}><div className="flex min-h-screen"><aside className="hidden w-[252px] flex-col border-r border-[#dbe4de] bg-white px-4 py-6 lg:flex"><Logo brandColor={workspace.tenant.brandColor} portalName={workspace.tenant.portalName} logoUrl={workspace.tenant.logoUrl} /><div className="mt-10 px-2"><p className="text-[10px] font-black tracking-[.15em] text-[#8b9b9b]">{isCoach ? "COACH WORKSPACE" : "CLIENT WORKSPACE"}</p><p className="mt-2 font-bold leading-5">{workspace.tenant.portalName}</p></div><nav className="mt-7 space-y-1">{navItems.filter(item => isCoach || !item.coachOnly).map(item => { const Icon = item.icon; return <button key={item.id} onClick={() => setPanel(item.id)} className={`flex w-full items-center gap-3 rounded-xl px-3 py-2.5 text-sm font-bold transition ${panel === item.id ? "bg-[#e5f3ed] text-[#0f766e]" : "text-[#587176] hover:bg-[#f2f6f4]"}`}><Icon size={17} />{item.label}</button>; })}</nav><div className="mt-auto rounded-2xl bg-[#102a31] p-4 text-white"><p className="text-xs font-bold text-[#8fd3c2]">BETWEEN SESSIONS</p><p className="mt-2 text-sm font-semibold leading-5">Structure creates visibility. Coaching creates change.</p></div></aside><div className="min-w-0 flex-1"><header className="sticky top-0 z-20 flex items-center justify-between border-b border-[#dce5df] bg-[#f6f4ee]/90 px-5 py-4 backdrop-blur-lg lg:px-8"><div className="flex items-center gap-3 lg:hidden"><button onClick={() => setMobileOpen(!mobileOpen)} className="rounded-lg p-2"><Menu size={21} /></button><Logo brandColor={workspace.tenant.brandColor} portalName={workspace.tenant.portalName} logoUrl={workspace.tenant.logoUrl} /></div><div className="hidden lg:block"><p className="text-xs font-bold tracking-[.12em] text-[#778e91]">{panel === "overview" ? "WORKSPACE OVERVIEW" : panel.toUpperCase()}</p><p className="mt-1 text-sm font-bold text-[#203d43]">{workspace.tenant.organizationName}</p></div><div className="flex items-center gap-3"><button onClick={downloadExport} className="hidden items-center gap-2 rounded-lg px-2 py-2 text-sm font-bold text-[#577278] hover:bg-white sm:flex"><Download size={16} /> Export</button><button className="flex h-9 w-9 items-center justify-center rounded-xl bg-[#dceee7] text-sm font-black text-[#0f766e]" title={boot.user.name || "Account"}>{(boot.user.name || "V").slice(0, 1).toUpperCase()}</button></div></header>{mobileOpen && <nav className="border-b border-[#dce5df] bg-white p-3 lg:hidden">{navItems.filter(item => isCoach || !item.coachOnly).map(item => { const Icon = item.icon; return <button key={item.id} onClick={() => { setPanel(item.id); setMobileOpen(false); }} className={`flex w-full items-center gap-3 rounded-lg px-3 py-2.5 text-sm font-bold ${panel === item.id ? "bg-[#e5f3ed] text-[#0f766e]" : "text-[#587176]"}`}><Icon size={16} /> {item.label}</button>; })}</nav>}<main className="mx-auto max-w-7xl px-5 py-7 lg:px-8 lg:py-9">{panel === "overview" ? <><section className="flex flex-col gap-5 sm:flex-row sm:items-end sm:justify-between"><div><p className="eyebrow">{isCoach ? "Client visibility" : "Your execution route"}</p><h1 className="mt-2 text-3xl font-semibold tracking-[-.055em] sm:text-4xl">{isCoach ? "See who needs your attention." : "One clear route, right now."}</h1><p className="mt-3 max-w-2xl leading-7 text-[#607a7e]">{isCoach ? "Progress, capacity, missed actions and reroute signals — before the next coaching call." : "Focus on the next meaningful action, then report what changed."}</p></div>{isCoach && <InviteClient tenantId={workspace.tenant.id} onCreated={() => utils.workspace.bootstrap.invalidate()} />}</section><div className="mt-8 grid gap-4 md:grid-cols-2 xl:grid-cols-3">{cards.map((card: any) => <button key={card.id} onClick={() => { setSelectedClientId(card.id); setPanel(isCoach ? "overview" : "today"); }} className="vr-card group p-5 text-left transition hover:-translate-y-0.5 hover:border-[#9cc9bc] hover:shadow-[0_14px_35px_rgba(17,64,59,.09)]"><div className="flex items-start justify-between gap-3"><div className="flex min-w-0 items-center gap-3"><div className="flex h-10 w-10 shrink-0 items-center justify-center rounded-xl bg-[#e7f3ee] text-sm font-black text-[#0f766e]">{card.name.split(" ").map((word: string) => word[0]).join("").slice(0,2)}</div><div className="min-w-0"><div className="flex items-center gap-2"><p className="truncate font-bold">{card.name}</p>{card.isDemo && <span className="rounded bg-[#eef2f0] px-1.5 py-0.5 text-[9px] font-black tracking-wide text-[#72878a]">SAMPLE</span>}</div><p className="mt-0.5 truncate text-xs text-[#73898c]">{card.primaryGoal}</p></div></div>{card.attention ? <CircleAlert size={18} className="shrink-0 text-[#bd7b2b]" /> : <CheckCircle2 size={18} className="shrink-0 text-[#0f766e]" />}</div><div className="mt-5 h-1.5 overflow-hidden rounded-full bg-[#e6eeea]"><div className="h-full rounded-full bg-[#0f766e]" style={{ width: `${card.progress}%` }} /></div><div className="mt-3 grid grid-cols-3 gap-2 text-xs"><div><p className="text-[#829598]">Progress</p><p className="mt-1 font-bold">{card.progress}%</p></div><div><p className="text-[#829598]">Capacity</p><p className="mt-1 font-bold capitalize">{card.capacity}</p></div><div><p className="text-[#829598]">Route</p><p className="mt-1 font-bold capitalize">{card.routeStatus.replace("_", " ")}</p></div></div><div className="mt-4 flex items-center justify-between border-t border-[#e7eeea] pt-3 text-xs font-bold text-[#5d777a]"><span>{card.currentMilestone}</span><ChevronRight size={15} className="transition group-hover:translate-x-0.5" /></div></button>)}</div>{!cards.length && <div className="vr-card mt-8 p-10 text-center"><Users className="mx-auto text-[#0f766e]" /><h2 className="mt-4 text-2xl font-semibold">Your workspace is ready for the first client.</h2><p className="mx-auto mt-2 max-w-md leading-7 text-[#607a7e]">Create an invitation to give a client a secure route to onboarding and their first coach-approved plan.</p>{isCoach && <div className="mt-6"><InviteClient tenantId={workspace.tenant.id} onCreated={() => utils.workspace.bootstrap.invalidate()} /></div>}</div>}</> : panel === "settings" && isCoach ? <BrandSettings tenant={workspace.tenant} terminology={terminology} /> : activeClientId ? <ClientWorkspace tenantId={workspace.tenant.id} clientId={activeClientId} role={workspace.membership.role} terminology={terminology} panel={panel} setPanel={setPanel} onBack={() => setPanel("overview")} /> : <div className="vr-card p-8">Choose a client to continue.</div>}</main></div></div></div>;
}

export default function Home() {
  const me = trpc.auth.me.useQuery();
  const boot = trpc.workspace.bootstrap.useQuery(undefined, { enabled: Boolean(me.data) });
  if (me.isLoading || (me.data && boot.isLoading)) return <div className="grid min-h-screen place-items-center bg-[#f6f4ee]"><div className="text-center"><Logo /><Loader2 className="mx-auto mt-5 animate-spin text-[#0f766e]" /><p className="mt-3 text-sm font-semibold text-[#607a7d]">Opening VisionRoute…</p></div></div>;
  if (!me.data) return <MarketingSite />;
  if (boot.error) return <main className="grid min-h-screen place-items-center bg-[#f6f4ee] p-5"><div className="vr-card max-w-md p-8"><CircleAlert className="text-[#b7534a]" /><h1 className="mt-4 text-2xl font-bold">Workspace unavailable</h1><p className="mt-2 leading-7 text-[#5d777b]">{boot.error.message}</p><button onClick={() => boot.refetch()} className="vr-button mt-6">Try again</button></div></main>;
  if (!boot.data?.workspace) return <WorkspaceSetup userName={me.data.name} />;
  return <WorkspaceShell boot={boot.data} />;
}
